//! Runtime for Rust generated by `n64rusty-translator`.
//!
//! Deliberately tiny and dependency-free: generated code depends only on this
//! crate, so edits to the translator, hooks or host do not rebuild it.
//!
//! It holds the guest CPU state ([`Ctx`]), big-endian guest RAM ([`Memory`])
//! and the single call dispatch point ([`Ctx::call`]) through which every
//! guest call goes, so any guest function can be overridden by address.

#![forbid(unsafe_code)]

use std::collections::HashMap;

mod fpu;
mod memory;

pub use fpu::{cvt_l, cvt_w, fcmp, Round};
pub use memory::{Io, Memory};

/// Crate version, checked against the version recorded in generated code.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// A recompiled (or host-written) guest function.
pub type GuestFn = fn(&mut Ctx);

/// Sign-extends a 32-bit result to a 64-bit register value, as the VR4300
/// does for every 32-bit operation.
#[inline(always)]
pub const fn sx32(v: u32) -> u64 {
    v as i32 as i64 as u64
}

/// Guest CPU state plus memory and the function table.
pub struct Ctx {
    /// General-purpose registers. `r[0]` is never written by generated code.
    pub r: [u64; 32],
    /// Multiply/divide result register HI.
    pub hi: u64,
    /// Multiply/divide result register LO.
    pub lo: u64,
    /// Floating-point registers, raw. See [`Ctx::fr`] for how singles and
    /// doubles map onto them.
    pub f: [u64; 32],
    /// Floating-point control/status register (FCR31): rounding mode in
    /// bits 0-1, compare condition in bit 23.
    pub fcr31: u32,
    /// The Status register's FR bit. `true`: 32 registers of 64 bits.
    /// `false`: MIPS II layout, where single `n` (odd) is the high half of
    /// `f[n - 1]` and doubles live in even registers. The console's boot
    /// code sets FR, so it defaults to `true`.
    pub fr: bool,
    /// Guest RAM.
    pub mem: Memory,
    funcs: HashMap<u32, GuestFn>,
    overrides: HashMap<u32, GuestFn>,
    overlays: Vec<Overlay>,
    /// Overlays currently in RAM, as indexes into `overlays`.
    loaded: Vec<usize>,
    /// The most recent call targets, oldest first once full; see
    /// [`Ctx::recent_calls`].
    trace: [u32; TRACE_LEN],
    /// Number of calls made through [`Ctx::call`].
    pub calls: u64,
    /// Current call depth.
    pub depth: u32,
    /// COP0 (system control) registers, as written by MTC0.
    pub cop0: [u32; 32],
    /// Virtual time in COP0 Count ticks: advances by [`COUNT_PER_CALL`]
    /// per call, and hosts move it forward when the game waits.
    pub clock: u64,
    /// When `clock` reaches this, the next call first runs `on_deadline`.
    /// Hosts use it to deliver interrupts (retrace, timers) to a game that
    /// is busy and never blocks.
    pub deadline: u64,
    /// See [`Ctx::deadline`].
    pub on_deadline: Option<GuestFn>,
}

struct Overlay {
    rom: u32,
    ram: u32,
    len: u32,
    funcs: HashMap<u32, GuestFn>,
}

/// How far the virtual COP0 Count register advances per call.
pub const COUNT_PER_CALL: u32 = 64;

/// How many recent calls [`Ctx`] remembers for crash reports.
pub const TRACE_LEN: usize = 64;

impl Ctx {
    /// A context with zeroed registers and the given RAM.
    pub fn new(mem: Memory) -> Self {
        Self {
            r: [0; 32],
            hi: 0,
            lo: 0,
            f: [0; 32],
            fcr31: 0,
            fr: true,
            mem,
            funcs: HashMap::new(),
            overrides: HashMap::new(),
            overlays: Vec::new(),
            loaded: Vec::new(),
            trace: [0; TRACE_LEN],
            calls: 0,
            depth: 0,
            cop0: [0; 32],
            clock: 0,
            deadline: u64::MAX,
            on_deadline: None,
        }
    }

    /// Registers a recompiled function at its guest address.
    pub fn register(&mut self, addr: u32, f: GuestFn) {
        self.funcs.insert(addr, f);
    }

    /// Replaces the function at `addr`. Overrides win over registered
    /// functions, so a hook can stand in for any guest routine.
    pub fn set_override(&mut self, addr: u32, f: GuestFn) {
        self.overrides.insert(addr, f);
    }

    /// Removes an override, restoring the registered function.
    pub fn clear_override(&mut self, addr: u32) {
        self.overrides.remove(&addr);
    }

    /// Registers the functions of code the game copies from the cartridge
    /// at run time: `len` bytes from ROM offset `rom` placed at `ram`.
    /// They are only called while that copy is in RAM (see
    /// [`Ctx::overlay_loaded`]), so overlays sharing an address range
    /// dispatch to whichever one is loaded.
    pub fn register_overlay(&mut self, rom: u32, ram: u32, len: u32, funcs: &[(u32, GuestFn)]) {
        self.overlays.push(Overlay {
            rom,
            ram,
            len,
            funcs: funcs.iter().copied().collect(),
        });
    }

    /// Records that `len` bytes from ROM offset `rom` were copied to `ram`.
    /// Overlays overwritten by the copy are unloaded and an overlay that
    /// starts at exactly this copy is loaded.
    pub fn overlay_loaded(&mut self, rom: u32, ram: u32, len: u32) {
        let (lo, hi) = (ram, ram.wrapping_add(len));
        let ovl = &self.overlays;
        self.loaded.retain(|&i| {
            let o = &ovl[i];
            o.ram.wrapping_add(o.len) <= lo || o.ram >= hi
        });
        for (i, o) in self.overlays.iter().enumerate() {
            if o.rom == rom && o.ram == ram {
                self.loaded.push(i);
            }
        }
    }

    /// The function at `addr`: an override, a loaded overlay's, or a
    /// registered one.
    fn lookup(&self, addr: u32) -> Option<GuestFn> {
        if let Some(f) = self.overrides.get(&addr) {
            return Some(*f);
        }
        for &i in self.loaded.iter().rev() {
            if let Some(f) = self.overlays[i].funcs.get(&addr) {
                return Some(*f);
            }
        }
        self.funcs.get(&addr).copied()
    }

    /// Calls the guest function at `addr`. Every call in generated code goes
    /// through here.
    pub fn call(&mut self, addr: u32) {
        let f = self.lookup(addr);
        self.trace[(self.calls % TRACE_LEN as u64) as usize] = addr;
        self.calls += 1;
        self.clock = self.clock.wrapping_add(u64::from(COUNT_PER_CALL));
        if self.clock >= self.deadline {
            if let Some(h) = self.on_deadline {
                self.deadline = u64::MAX;
                h(self);
            }
        }
        match f {
            Some(f) => {
                self.depth += 1;
                f(self);
                self.depth -= 1;
            }
            None => panic!("call to unknown guest function {addr:#010x}"),
        }
    }

    /// MFC0. Count (register 9) reads [`Ctx::clock`], so runs are
    /// reproducible.
    pub fn mfc0(&self, n: usize) -> u64 {
        match n {
            9 => sx32(self.clock as u32),
            _ => sx32(self.cop0[n]),
        }
    }

    /// MTC0. Writes are stored; none of them has a side effect yet.
    pub fn mtc0(&mut self, n: usize, v: u64) {
        self.cop0[n] = v as u32;
    }

    /// Whether a function is registered or overridden at `addr`.
    pub fn has_function(&self, addr: u32) -> bool {
        self.lookup(addr).is_some()
    }

    /// The most recent call targets, oldest first.
    pub fn recent_calls(&self) -> Vec<u32> {
        let n = self.calls.min(TRACE_LEN as u64) as usize;
        let start = self.calls as usize - n;
        (start..start + n)
            .map(|k| self.trace[k % TRACE_LEN])
            .collect()
    }

    /// Signed 32-bit divide (DIV). Division by zero and overflow give the
    /// VR4300's results instead of trapping.
    pub fn div(&mut self, a: u64, b: u64) {
        let n = a as i32;
        let d = b as i32;
        if d == 0 {
            self.lo = if n < 0 { 1 } else { u64::MAX };
            self.hi = sx32(n as u32);
        } else {
            self.lo = sx32(n.wrapping_div(d) as u32);
            self.hi = sx32(n.wrapping_rem(d) as u32);
        }
    }

    /// Unsigned 32-bit divide (DIVU).
    pub fn divu(&mut self, a: u64, b: u64) {
        let n = a as u32;
        let d = b as u32;
        match (n.checked_div(d), n.checked_rem(d)) {
            (Some(q), Some(r)) => {
                self.lo = sx32(q);
                self.hi = sx32(r);
            }
            _ => {
                self.lo = u64::MAX;
                self.hi = sx32(n);
            }
        }
    }

    /// Signed 64-bit divide (DDIV).
    pub fn ddiv(&mut self, a: u64, b: u64) {
        let n = a as i64;
        let d = b as i64;
        if d == 0 {
            self.lo = if n < 0 { 1 } else { u64::MAX };
            self.hi = n as u64;
        } else {
            self.lo = n.wrapping_div(d) as u64;
            self.hi = n.wrapping_rem(d) as u64;
        }
    }

    /// Unsigned 64-bit divide (DDIVU).
    pub fn ddivu(&mut self, a: u64, b: u64) {
        match (a.checked_div(b), a.checked_rem(b)) {
            (Some(q), Some(r)) => {
                self.lo = q;
                self.hi = r;
            }
            _ => {
                self.lo = u64::MAX;
                self.hi = a;
            }
        }
    }

    /// Signed 32-bit multiply (MULT).
    pub fn mult(&mut self, a: u64, b: u64) {
        let p = (a as i32 as i64).wrapping_mul(b as i32 as i64) as u64;
        self.lo = sx32(p as u32);
        self.hi = sx32((p >> 32) as u32);
    }

    /// Unsigned 32-bit multiply (MULTU).
    pub fn multu(&mut self, a: u64, b: u64) {
        let p = (a as u32 as u64) * (b as u32 as u64);
        self.lo = sx32(p as u32);
        self.hi = sx32((p >> 32) as u32);
    }

    /// Signed 64-bit multiply (DMULT).
    pub fn dmult(&mut self, a: u64, b: u64) {
        let p = (a as i64 as i128).wrapping_mul(b as i64 as i128) as u128;
        self.lo = p as u64;
        self.hi = (p >> 64) as u64;
    }

    /// Unsigned 64-bit multiply (DMULTU).
    pub fn dmultu(&mut self, a: u64, b: u64) {
        let p = (a as u128) * (b as u128);
        self.lo = p as u64;
        self.hi = (p >> 64) as u64;
    }

    /// Called by generated code for an instruction the translator does not
    /// support yet.
    #[cold]
    pub fn unimplemented(&mut self, pc: u32, word: u32) -> ! {
        panic!("unimplemented instruction {word:#010x} at {pc:#010x}")
    }
}

/// Called by generated code when execution reaches an address inside a
/// function that is not a known block start (for example a jump table target
/// that was not discovered).
#[cold]
pub fn bad_pc(func: u32, pc: u32) -> ! {
    panic!("jump to {pc:#010x} inside function {func:#010x} is not a known block start")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn deadline_runs_hook_once_before_the_call() {
        fn hook(c: &mut Ctx) {
            c.r[2] += 1;
        }
        fn callee(c: &mut Ctx) {
            c.r[3] = c.r[2];
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register(0x8000_1000, callee);
        c.on_deadline = Some(hook);
        c.deadline = u64::from(COUNT_PER_CALL) * 2;
        c.call(0x8000_1000);
        assert_eq!((c.r[2], c.r[3]), (0, 0));
        c.call(0x8000_1000);
        assert_eq!((c.r[2], c.r[3]), (1, 1));
        // Disarmed until the host sets a new deadline.
        c.call(0x8000_1000);
        assert_eq!(c.r[2], 1);
    }

    #[test]
    fn overlays_load_and_unload_with_copies() {
        fn a(c: &mut Ctx) {
            c.r[2] = 1;
        }
        fn b(c: &mut Ctx) {
            c.r[2] = 2;
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register_overlay(0x1000, 0x8010_0000, 0x100, &[(0x8010_0000, a)]);
        c.register_overlay(0x2000, 0x8010_0000, 0x100, &[(0x8010_0000, b)]);
        assert!(!c.has_function(0x8010_0000));
        c.overlay_loaded(0x2000, 0x8010_0000, 0x100);
        c.call(0x8010_0000);
        assert_eq!(c.r[2], 2);
        c.overlay_loaded(0x1000, 0x8010_0000, 0x100);
        c.call(0x8010_0000);
        assert_eq!(c.r[2], 1);
        // A copy of something else over it unloads it.
        c.overlay_loaded(0x9000, 0x8010_0080, 0x10);
        assert!(!c.has_function(0x8010_0000));
    }

    #[test]
    fn version_is_set() {
        assert!(!VERSION.is_empty());
    }

    #[test]
    fn div_edge_cases() {
        let mut c = Ctx::new(Memory::new(16));
        c.div(7, 0);
        assert_eq!((c.lo, c.hi), (u64::MAX, 7));
        c.div(sx32(-7i32 as u32), 0);
        assert_eq!((c.lo, c.hi), (1, sx32(-7i32 as u32)));
        c.div(sx32(i32::MIN as u32), sx32(-1i32 as u32));
        assert_eq!((c.lo, c.hi), (sx32(i32::MIN as u32), 0));
        c.div(sx32(-7i32 as u32), 2);
        assert_eq!((c.lo, c.hi), (sx32(-3i32 as u32), sx32(-1i32 as u32)));
        c.divu(0xFFFF_FFFF, 0);
        assert_eq!((c.lo, c.hi), (u64::MAX, u64::MAX));
        c.ddiv(i64::MIN as u64, u64::MAX);
        assert_eq!((c.lo, c.hi), (i64::MIN as u64, 0));
    }

    #[test]
    fn mult_splits_and_sign_extends() {
        let mut c = Ctx::new(Memory::new(16));
        c.multu(0xFFFF_FFFF, 0xFFFF_FFFF);
        assert_eq!(c.lo, 1);
        assert_eq!(c.hi, sx32(0xFFFF_FFFE));
        c.mult(sx32(-2i32 as u32), 3);
        assert_eq!((c.lo, c.hi), (sx32(-6i32 as u32), u64::MAX));
        c.dmultu(u64::MAX, 2);
        assert_eq!((c.lo, c.hi), (u64::MAX - 1, 1));
    }

    #[test]
    fn overlays_dispatch_by_what_is_loaded() {
        fn a(c: &mut Ctx) {
            c.r[2] = 0xA;
        }
        fn b(c: &mut Ctx) {
            c.r[2] = 0xB;
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register_overlay(0x1000, 0x8010_0000, 0x100, &[(0x8010_0000, a)]);
        c.register_overlay(0x2000, 0x8010_0000, 0x200, &[(0x8010_0000, b)]);
        assert!(!c.has_function(0x8010_0000));
        c.overlay_loaded(0x1000, 0x8010_0000, 0x100);
        c.call(0x8010_0000);
        assert_eq!(c.r[2], 0xA);
        c.overlay_loaded(0x2000, 0x8010_0000, 0x200);
        c.call(0x8010_0000);
        assert_eq!(c.r[2], 0xB);
        // Data copied over it unloads it.
        c.overlay_loaded(0x9000, 0x8010_0080, 0x10);
        assert!(!c.has_function(0x8010_0000));
    }

    #[test]
    fn overrides_win() {
        fn a(c: &mut Ctx) {
            c.r[2] = 1;
        }
        fn b(c: &mut Ctx) {
            c.r[2] = 2;
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register(0x8000_0400, a);
        c.call(0x8000_0400);
        assert_eq!(c.r[2], 1);
        c.set_override(0x8000_0400, b);
        c.call(0x8000_0400);
        assert_eq!(c.r[2], 2);
        c.clear_override(0x8000_0400);
        c.call(0x8000_0400);
        assert_eq!(c.r[2], 1);
    }
}
